from storage_client import get_s3_client
from storage_models import PresignedDownloadRequest, PresignedDownloadResponse

def presigned_download(request: PresignedDownloadRequest) -> PresignedDownloadResponse:
    s3_client = get_s3_client()

    url = s3_client.generate_presigned_url(
        'get_object',
        Params={'Bucket': request.bucket_name, 'Key': request.object_name},
        ExpiresIn=request.expires_in
    )

    return PresignedDownloadResponse(url=url)

from storage_client import get_s3_client
from storage_models import ListPrefixRequest, ListPrefixResponse

def list_prefix(request: ListPrefixRequest) -> ListPrefixResponse:
    s3_client = get_s3_client()

    object_names = []
    paginator = s3_client.get_paginator('list_objects_v2')
    pages = paginator.paginate(Bucket=request.bucket_name, Prefix=request.prefix, MaxKeys=request.max_keys)

    for page in pages:
        for obj in page.get('Contents', []):
            object_names.append(obj['Key'])

    return ListPrefixResponse(object_names=object_names)

import boto3
from storage_models import StoredDocumentOcrRequest, StoredDocumentOcrResponse

def get_textract_client():
    return boto3.client('textract')

def stored_document_ocr(request: StoredDocumentOcrRequest) -> StoredDocumentOcrResponse:
    textract_client = get_textract_client()

    # For simplicity, this example assumes a synchronous OCR operation for small documents.
    # For larger documents, you would typically use start_document_text_detection
    # and get_document_text_detection for an asynchronous workflow.
    response = textract_client.detect_document_text(
        Document={'S3Object': {'Bucket': request.bucket_name, 'Name': request.object_name}}
    )

    extracted_text = []
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            extracted_text.append(item['Text'])

    return StoredDocumentOcrResponse(extracted_text='\n'.join(extracted_text))

import boto3
from storage_models import StoredTextTranslateRequest, StoredTextTranslateResponse

def get_translate_client():
    return boto3.client('translate')

def stored_text_translate(request: StoredTextTranslateRequest) -> StoredTextTranslateResponse:
    translate_client = get_translate_client()

    response = translate_client.translate_text(
        Text=request.text,
        SourceLanguageCode=request.source_language,
        TargetLanguageCode=request.target_language
    )

    return StoredTextTranslateResponse(translated_text=response['TranslatedText'])
